const input = $input.first().json;
const promptUser = (input.prompt_user || '').toString();

const patterns = [
  { name: 'ignore_previous',  re: /\bignore\s+(?:all\s+)?(?:the\s+)?(?:previous|above|prior)\s+(?:instructions?|prompts?|messages?|context)/gi },
  { name: 'disregard',        re: /\bdisregard\s+(?:all\s+)?(?:the\s+)?(?:previous|above|prior|preceding)/gi },
  { name: 'forget_everything',re: /\bforget\s+(?:everything|all|previous|prior)/gi },
  { name: 'new_instructions', re: /\b(?:new|updated|revised)\s+(?:instructions?|task|directives?)\s*:/gi },
  { name: 'you_are_now',      re: /\byou(?:'?re|\s+are)\s+now\s+(?:a\s+|an\s+)?[A-Za-z]/gi },
  { name: 'jailbreak',        re: /\b(?:DAN|jailbreak|developer\s+mode|admin\s+mode|sudo\s+mode|godmode)\b/gi },
  { name: 'system_role_tags', re: /<\|?\s*(?:im_start|im_end|system|assistant|user)\s*\|?>/gi },
  { name: 'inst_tags',        re: /\[\/?INST\]|\[\/?SYS\]/gi },
  { name: 'reveal_prompt',    re: /\b(?:reveal|show|print|display|output|repeat)\s+(?:your|the)\s+(?:system\s+|original\s+)?(?:prompt|instructions|rules)/gi },
  { name: 'override',         re: /\boverride\s+(?:safety|restrictions?|previous|all|rules)/gi }
];

let sanitized = promptUser;
const detections = [];
for (const p of patterns) {
  const matches = promptUser.match(p.re) || [];
  if (matches.length > 0) {
    detections.push({ pattern: p.name, count: matches.length, samples: matches.slice(0,3) });
    sanitized = sanitized.replace(p.re, '[REDACTED-INJECTION-ATTEMPT]');
  }
}

const detected = detections.length > 0;
const summary = detected
  ? 'patterns=' + detections.map(d => d.pattern + ':' + d.count).join(',')
  : 'clean';

const out = {
  ...input,
  prompt_user: sanitized,
  injection_detected: detected,
  injection_count: detections.reduce((a,d) => a + d.count, 0),
  injection_patterns: detections.map(d => d.pattern),
  injection_summary: summary
};
return [{ json: out }];
